 "content": "from collections import Counter


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            points = set()
            while stack:
                y, x = stack.pop()
                points.add((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            result.append((color, points))
    return result


def _l_corner(points):
    ys = [y for y, x in points]
    xs = [x for y, x in points]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    if y0 == y1 or x0 == x1 or len(points) != (y1 - y0 + 1) + (x1 - x0 + 1) - 1:
        return None
    for cy, cx in ((y0, x0), (y0, x1), (y1, x0), (y1, x1)):
        if ({(y, cx) for y in range(y0, y1 + 1)} | {(cy, x) for x in range(x0, x1 + 1)}) == points:
            return cy, cx
    return None


def transform(grid):
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = _components(grid, background)
    guides = []
    for color, points in components:
        corner = _l_corner(points)
        if corner is not None:
            guides.append((len(points), color, points, corner))
    if not guides:
        return [row[:] for row in grid]

    _, guide_color, guide, (cy, cx) = max(guides)
    y0, y1 = min(y for y, x in guide), max(y for y, x in guide)
    x0, x1 = min(x for y, x in guide), max(x for y, x in guide)
    cavity_y = range(y0, cy) if cy == y1 else range(cy + 1, y1 + 1)
    cavity_x = range(x0, cx) if cx == x1 else range(cx + 1, x1 + 1)
    cavity = {(y, x) for y in cavity_y for x in cavity_x}

    choices = []
    for color, points in components:
        if color == guide_color or all(p in cavity for p in points):
            continue
        distance = min(abs(y - gy) + abs(x - gx) for y, x in points for gy, gx in guide)
        choices.append((distance, -len(points), color, points))
    if not choices:
        return [row[:] for row in grid]
    _, _, _, selected = min(choices)
    out = [row[:] for row in grid]
    for y, x in selected:
        out[y][x] = guide_color
    return out


